  SWIG_Python_SetConstant(d, "THOST_TERT_RESUME",SWIG_From_int(static_cast< int >(THOST_TERT_RESUME)));
  SWIG_Python_SetConstant(d, "THOST_TERT_QUICK",SWIG_From_int(static_cast< int >(THOST_TERT_QUICK)));
  SWIG_Python_SetConstant(d, "THOST_TERT_NONE",SWIG_From_int(static_cast< int >(THOST_TERT_NONE)));
