  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_IDCard",SWIG_From_char(static_cast< char >('1')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_OfficerIDCard",SWIG_From_char(static_cast< char >('2')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_PoliceIDCard",SWIG_From_char(static_cast< char >('3')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_SoldierIDCard",SWIG_From_char(static_cast< char >('4')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_HouseholdRegister",SWIG_From_char(static_cast< char >('5')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_Passport",SWIG_From_char(static_cast< char >('6')));
  SWIG_Python_SetConstant(d, "THOST_FTDC_ICT_TaiwanCompatriotIDCard",SWIG_From_char(static_cast< char >('7')));
